 if(!Array.isArray(e.corpses)||e.corpses.length>4||new Set(e.corpses.map(c=>c.id)).size!==e.corpses.length||e.corpses.some(c=>!exact(c,'id,owner,x,y,attack,expires')||!int(c.id,1,e.nextCorpse-1)||!int(c.owner,1,s.players.length-1)||!int(c.x,0,s.board.columns-1)||!int(c.y,0,s.board.rows-1)||!int(c.attack,0,100)||!int(c.expires,1)))return false;
